// ── Step 1: Define the Target Interface ────────────────────────
// This is what your system already expects. Written once, never changes.
interface PaymentProcessor {
  charge(amount: number, currency: string, note: string): Promise<void>;
}

// ── Step 2: Adaptee #1 — Stripe SDK (third-party, cannot modify) ─
class StripeSDK {
  async createCharge(opts: {
    amount: number;
    currency: string;
    description: string;
    idempotencyKey?: string;
  }): Promise<{ id: string; status: string }> {
    // Real SDK would make an HTTP call
    console.log(`[Stripe] Charging ${opts.amount} ${opts.currency}: ${opts.description}`);
    return { id: 'ch_stripe_123', status: 'succeeded' };
  }
}

// ── Step 3: Adaptee #2 — Legacy PayPal client (old internal module) ─
class LegacyPayPalClient {
  async sendPayment(
    total: number,
    curr: string,
    memo: string
  ): Promise<{ transactionId: string }> {
    console.log(`[PayPal] Sending ${total} ${curr} — memo: ${memo}`);
    return { transactionId: 'pp_456' };
  }
}

// ── Step 4: Adapter for Stripe ──────────────────────────────────
// Implements Target, wraps Adaptee via composition
class StripeAdapter implements PaymentProcessor {
  private readonly stripe: StripeSDK;

  constructor(stripe: StripeSDK) {
    this.stripe = stripe;
  }

  async charge(amount: number, currency: string, note: string): Promise<void> {
    // Translation: Target call → Adaptee call.
    // Stripe wants integer minor units (cents) and lowercase ISO currency codes.
    const result = await this.stripe.createCharge({
      amount: Math.round(amount * 100),
      currency: currency.toLowerCase(),
      description: note,
      // Production: use a key that is STABLE per order (e.g. the order ID) so a
      // retried request is not charged twice — a timestamp would not be.
      idempotencyKey: `order_${note}`,
    });
    console.log(`StripeAdapter: done, id=${result.id}, status=${result.status}`);
  }
}

// ── Step 5: Adapter for Legacy PayPal ───────────────────────────
class PayPalAdapter implements PaymentProcessor {
  private readonly paypal: LegacyPayPalClient;

  constructor(paypal: LegacyPayPalClient) {
    this.paypal = paypal;
  }

  async charge(amount: number, currency: string, note: string): Promise<void> {
    // Translation: different parameter order, different method name
    const result = await this.paypal.sendPayment(amount, currency, note);
    console.log(`PayPalAdapter: done, transactionId=${result.transactionId}`);
  }
}

// ── Step 6: Client — knows only the Target Interface ───────────
class OrderService {
  constructor(private readonly processor: PaymentProcessor) {}

  async placeOrder(amount: number, currency: string, item: string): Promise<void> {
    console.log(`Placing order for ${item}...`);
    await this.processor.charge(amount, currency, `Order: ${item}`);
    console.log('Order complete!\n');
  }
}

// ── Wire it up — zero changes to OrderService either way ─────────
async function main() {
  const stripeOrder = new OrderService(new StripeAdapter(new StripeSDK()));
  await stripeOrder.placeOrder(49.99, 'USD', 'Pro Subscription');
  // Placing order for Pro Subscription...
  // [Stripe] Charging 4999 usd: Order: Pro Subscription
  // StripeAdapter: done, id=ch_stripe_123, status=succeeded
  // Order complete!

  const paypalOrder = new OrderService(new PayPalAdapter(new LegacyPayPalClient()));
  await paypalOrder.placeOrder(29.00, 'EUR', 'Ebook Bundle');
  // Placing order for Ebook Bundle...
  // [PayPal] Sending 29 EUR — memo: Order: Ebook Bundle
  // PayPalAdapter: done, transactionId=pp_456
  // Order complete!
}
main();

sections.content:
The Adapter pattern provides a significant but often underappreciated benefit: **it makes code that talks to external systems trivially testable**.

Consider `OrderService` calling a real payment processor. Without the Adapter pattern, `OrderService` likely calls the Stripe SDK directly. Unit-testing it means either:
- Actually hitting Stripe's API (slow, requires network, costs money)
- Using a complex mocking library to patch module internals (fragile, ties tests to implementation)

With the Adapter pattern, because `OrderService` depends on the `PaymentProcessor` **interface**, your test can inject a simple fake:

```typescript
class FakePaymentProcessor implements PaymentProcessor {
  public charged: Array<{ amount: number; currency: string; note: string }> = [];

  async charge(amount: number, currency: string, note: string): Promise<void> {
    this.charged.push({ amount, currency, note });
  }
}

test('placeOrder calls processor.charge with correct arguments', async () => {
  const fakeProcessor = new FakePaymentProcessor();
  const service = new OrderService(fakeProcessor);
  await service.placeOrder(99.99, 'USD', 'Premium Plan');
  expect(fakeProcessor.charged).toHaveLength(1);
  expect(fakeProcessor.charged[0].amount).toBe(99.99);
});
```

The `FakePaymentProcessor` does not need any mocking framework. It is just a class that implements the same interface. This is the **test double** pattern, and it falls naturally out of Adapter-friendly design.

Separately, you can test the `StripeAdapter` in isolation: inject a mock `StripeSDK` and verify that `charge(100, 'USD', 'note')` results in a call to `createCharge({ amount: 100, currency: 'USD', description: 'note', ... })`. You are testing the translation logic, not the business logic.

The separation of concerns is clean: **adapters are tested for correct translation; services are tested for correct business logic; integrations are tested end-to-end against real or sandboxed external systems**.

