// ── Concrete test double — no mocking library needed ───────────
interface Logger {
  log(message: string): void;
  warn(message: string): void;
  error(message: string, err?: unknown): void;
}

class ConsoleLogger implements Logger {
  log(message: string) { console.log(message); }
  warn(message: string) { console.warn(message); }
  error(message: string, err?: unknown) { console.error(message, err); }
}

// Imagine a legacy in-house logging SDK with a different API:
class LegacyLogSDK {
  info(data: { msg: string; level: string }) { /* legacy API */ }
  warning(data: { msg: string }) { /* legacy API */ }
  err(data: { msg: string; stack?: string }) { /* legacy API */ }
}

// Adapter makes the legacy SDK compatible with your Logger interface:
class LegacyLogAdapter implements Logger {
  constructor(private readonly sdk: LegacyLogSDK) {}

  log(message: string): void {
    this.sdk.info({ msg: message, level: 'info' });
  }

  warn(message: string): void {
    this.sdk.warning({ msg: message });
  }

  error(message: string, err?: unknown): void {
    const stack = err instanceof Error ? err.stack : undefined;
    this.sdk.err({ msg: message, stack });
  }
}

// ── Fake logger for tests — a test double, not an adapter ───────────────────
class InMemoryLogger implements Logger {
  readonly logs: string[] = [];
  readonly warnings: string[] = [];
  readonly errors: string[] = [];

  log(message: string) { this.logs.push(message); }
  warn(message: string) { this.warnings.push(message); }
  error(message: string) { this.errors.push(message); }
}

// Any service that depends on Logger can be tested with InMemoryLogger:
class UserRegistrationService {
  constructor(private readonly logger: Logger) {}

  register(email: string) {
    if (!email.includes('@')) {
      this.logger.error(`Invalid email: ${email}`);
      throw new Error('Invalid email');
    }
    this.logger.log(`User registered: ${email}`);
  }
}

// Test:
const fakeLogger = new InMemoryLogger();
const svc = new UserRegistrationService(fakeLogger);
svc.register('alice@example.com');
console.log(fakeLogger.logs); // ['User registered: alice@example.com']

// Production:
const prodLogger = new LegacyLogAdapter(new LegacyLogSDK());
const prodSvc = new UserRegistrationService(prodLogger);

