// ── Real-world pattern: HTTP client adapter ─────────────────────
// Many teams define an internal HttpClient interface to avoid
// coupling their codebase directly to Axios or fetch.

// Target Interface — what your services depend on
class HttpClient {
  // get(url, options?) → Promise<{ data, status }>
  async get(_url, _options) { throw new Error('Not implemented'); }
  async post(_url, _body, _options) { throw new Error('Not implemented'); }
}

// Adapter for Axios (third-party, different response shape)
class AxiosAdapter extends HttpClient {
  constructor(axiosInstance) {
    super();
    this._axios = axiosInstance;
  }
  async get(url, options = {}) {
    const res = await this._axios.get(url, options);
    // Translate Axios response shape to our interface contract
    return { data: res.data, status: res.status };
  }
  async post(url, body, options = {}) {
    const res = await this._axios.post(url, body, options);
    return { data: res.data, status: res.status };
  }
}

// Adapter for native fetch (different API entirely)
class FetchAdapter extends HttpClient {
  async get(url, options = {}) {
    const res = await fetch(url, { method: 'GET', headers: options.headers });
    const data = await res.json();
    return { data, status: res.status };
  }
  async post(url, body, options = {}) {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...options.headers },
      body: JSON.stringify(body),
    });
    const data = await res.json();
    return { data, status: res.status };
  }
}

// Fake for tests — no network, instant, deterministic
class FakeHttpClient extends HttpClient {
  constructor(responses = {}) {
    super();
    this._responses = responses; // { '/api/users': { data: [...], status: 200 } }
    this._calls = [];
  }
  async get(url, options = {}) {
    this._calls.push({ method: 'GET', url, options });
    return this._responses[url] ?? { data: null, status: 404 };
  }
  async post(url, body, options = {}) {
    this._calls.push({ method: 'POST', url, body, options });
    return this._responses[url] ?? { data: null, status: 201 };
  }
  // Test helper
  getCalls() { return this._calls; }
}

// Any service using HttpClient works with all three:
class UserApiService {
  constructor(httpClient) {
    this._http = httpClient;
  }
  async fetchUsers() {
    const { data, status } = await this._http.get('/api/users');
    if (status !== 200) throw new Error(`Unexpected status: ${status}`);
    return data;
  }
}

// In production:
// const userService = new UserApiService(new AxiosAdapter(axios.create({...})));

// In tests:
const fakeHttp = new FakeHttpClient({
  '/api/users': { data: [{ id: 1, name: 'Alice' }], status: 200 },
});
const svc = new UserApiService(fakeHttp);
svc.fetchUsers().then(users => {
  console.log(users); // [{ id: 1, name: 'Alice' }]
  console.log(fakeHttp.getCalls()); // [{ method: 'GET', url: '/api/users', options: {} }]
});
